import {PALADIN_IDS,PALADIN_SPECIES} from './paladin-data.js?v=0.90.41';
export const COURT_ENCOUNTER_CHANCE=.01,COURT_FLEE_CHANCE=.10;
export function courtState(state){const q=state.paladinCourt??={version:1,accepted:false,inscriptions:[],sequence:[],puzzle:false,commander:false,releasePending:false,released:false,choice:null,roamers:{}};if(state.defeatedTrainers?.includes('TRN-COURT-HUGH')||q.released)q.commander=true;if((q.version??1)<2){q.legacyProgress=!!(q.puzzle||q.commander||q.released);if(!q.legacyProgress)q.sequence=[];q.version=2;}q.inscriptions??=[];q.sequence??=[];q.roamers??={};for(const id of PALADIN_IDS){q.roamers[id]??={status:'roaming',unit:null,meetings:0};const row=q.roamers[id];if([...state.party||[],...state.reserve||[]].some(u=>u.species.id===id))row.status='captured';else if((state.dead||[]).some(u=>u.species.id===id)&&row.status==='roaming')row.status='killed';}return q;}
export function availablePaladins(state){const q=courtState(state);return q.released?PALADIN_IDS.filter(id=>q.roamers[id].status==='roaming'):[];}
export function rollCourtEncounter(state,random,route){const eligible=availablePaladins(state);if(!route?.tables?.length||!eligible.length||random()>=COURT_ENCOUNTER_CHANCE)return null;const id=eligible[Math.min(eligible.length-1,Math.floor(random()*eligible.length))],row=courtState(state).roamers[id];const max=Math.max(40,...route.tables.flatMap(t=>t.slots.map(s=>s.max_level||1)));return {speciesId:id,level:row.unit?.level||Math.min(200,max),phase:'ROAMING COURT',tableId:'PALADIN-COURT',roamerId:id,seed:'court:'+id+':'+(Math.floor(random()*4294967296)||1)};}
export function courtEnemy(state,encounter,create,hydrate){const row=courtState(state).roamers[encounter.roamerId];if(!row||row.status!=='roaming')return null;const u=row.unit?hydrate(structuredClone(row.unit)):create(encounter.speciesId,encounter.level,encounter.seed||'court:'+encounter.roamerId);u.uid='court:'+encounter.roamerId;row.meetings++;storeRoamer(state,u);return u;}
export function storeRoamer(state,unit,outcome=null){const id=unit.species.id;if(!PALADIN_IDS.includes(id))return false;const row=courtState(state).roamers[id];if(row.status!=='roaming'&&outcome!=='captured')return false;row.lastHp=unit.hp;row.level=unit.level;if(outcome==='captured'){row.status='captured';row.unit=null;}else if(unit.hp<=0||unit.dead){row.status='killed';row.unit=null;}else{row.unit=JSON.parse(JSON.stringify({...unit,species:{id},field:{},stages:{},abilityState:null,abilityBattle:null}));}return true;}
export function courtRound(state,battle,random){if(!battle.roamerId||battle.trainer)return false;const enemy=battle.enemies[0];storeRoamer(state,enemy,battle.outcome);if(battle.outcome||enemy.hp<=0||enemy.dead)return false;if(random()<COURT_FLEE_CHANCE){battle.outcome='roamer-fled';battle.log=enemy.species.name+' slips past your expedition and disappears into the undergrowth.';return true;}return false;}
export function courtJournal(state){const q=courtState(state);if(!q.accepted)return 'Take the northern old royal road from Western Orchards. Scout Agnes is at the Forgotten Turn. Hugh de Mowbray has researched Karolion’s lost court, hoping its chivalry can reform the First Light.';if(!q.released){const t=q.trials;return q.releasePending?'The regalia has been lifted. Return to the Empty Throne to finish the awakening.':!q.puzzle?'Restore the Shared Spring in Bannerwood and guide the linked Fire and Ice wardens in the Broken Procession. The trials honour the cats’ duty to protect their own type and keep each element in balance under Karolion. Then read the three reliefs at the Thirteen Plinths and complete the king’s oath. The Common Cause is contesting the road. Water trial: '+(t?.channels.solved?'restored':'unresolved')+'; elemental wardens: '+(t?.wardens.solved?'balanced':'unresolved')+'.':!q.commander?'Cross Crownfall Ravine. Darius and Hugh wait on the Sceptre Road for different reasons. Agnes can rest your living partners at the ravine camp.':'Hugh knows nothing of the regalia inside the Empty Throne. Examine the ancient cradle.';}return 'The regalia released the thirteen stewards. Every eligible route has a shared 1% court encounter chance. Each guardian is unique. '+PALADIN_SPECIES.filter(s=>s.legendaryRoamer).map(s=>{const r=q.roamers[s.id];return s.name+': '+(r.status==='captured'?'befriended':r.status==='killed'?'fallen':r.meetings?'roaming · seen '+r.meetings+' time'+(r.meetings===1?'':'s'):'roaming · unseen');}).join(' · ');}
